CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Circle member', avatar_url text, onboarded boolean NOT NULL DEFAULT false, clearout_choice boolean, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY edit_profile ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role='admin'), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
CREATE TABLE public.circles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), invite_token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.circles TO authenticated; GRANT ALL ON public.circles TO service_role;
ALTER TABLE public.circles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.circle_members (circle_id uuid REFERENCES public.circles(id) ON DELETE CASCADE, user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(circle_id,user_id));
GRANT SELECT ON public.circle_members TO authenticated; GRANT ALL ON public.circle_members TO service_role;
ALTER TABLE public.circle_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_member(c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.circle_members WHERE circle_id=c AND user_id=auth.uid()) $$;
CREATE POLICY member_circles ON public.circles FOR SELECT TO authenticated USING(public.is_member(id) OR public.is_admin());
CREATE POLICY own_memberships ON public.circle_members FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), circle_id uuid NOT NULL REFERENCES public.circles(id), giver_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120), description text NOT NULL DEFAULT '' CHECK(length(description)<=2000), condition text NOT NULL CHECK(condition IN('New','Like new','Good','Fair')), category text NOT NULL CHECK(category IN('Household','Furniture','Books','Puzzles & games','Garden','Pets','Clothing','Sports','Electronics','Other')), pickup_area text NOT NULL CHECK(pickup_area IN('Near campus','Downtown Berkeley','North Berkeley','South Berkeley','West Berkeley','Elmwood','Other general area')), photo_path text NOT NULL, status text NOT NULL DEFAULT 'available' CHECK(status IN('available','claimed','picked_up','thanked','expired','donated','removed')), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', reminded boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.items TO authenticated; GRANT ALL ON public.items TO service_role;
ALTER TABLE public.items ENABLE ROW LEVEL SECURITY;
CREATE POLICY circle_items ON public.items FOR SELECT TO authenticated USING(public.is_member(circle_id));
CREATE TABLE public.wishes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, circle_id uuid NOT NULL REFERENCES public.circles(id), text text NOT NULL CHECK(length(text) BETWEEN 1 AND 120), category text NOT NULL CHECK(category IN('Household','Furniture','Books','Puzzles & games','Garden','Pets','Clothing','Sports','Electronics','Other')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.wishes TO authenticated; GRANT ALL ON public.wishes TO service_role;
ALTER TABLE public.wishes ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_wishes ON public.wishes FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.is_member(circle_id));
CREATE TABLE public.claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES public.items(id), receiver_id uuid NOT NULL REFERENCES public.profiles(id), status text NOT NULL DEFAULT 'claimed' CHECK(status IN('claimed','pickup_arranged','picked_up','thanked','expired')), created_at timestamptz NOT NULL DEFAULT now(), pickup_by timestamptz NOT NULL DEFAULT now()+interval '48 hours', picked_up_at timestamptz);
GRANT SELECT ON public.claims TO authenticated; GRANT ALL ON public.claims TO service_role;
ALTER TABLE public.claims ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX one_active_claim ON public.claims(item_id) WHERE status IN('claimed','pickup_arranged');
CREATE POLICY participants_claims ON public.claims FOR SELECT TO authenticated USING(receiver_id=auth.uid() OR EXISTS(SELECT 1 FROM public.items i WHERE i.id=item_id AND i.giver_id=auth.uid()));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES public.claims(id), sender_id uuid NOT NULL REFERENCES public.profiles(id), text text NOT NULL CHECK(length(text) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY participants_messages ON public.messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.claims c WHERE c.id=claim_id));
CREATE TABLE public.events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), item_id uuid REFERENCES public.items(id), circle_id uuid REFERENCES public.circles(id), name text NOT NULL CHECK(name IN('circle_link_opened','item_link_opened','signed_up','joined_circle','wish_added','item_posted','post_nudge_shown','item_shared','match_created','match_notification_sent','swipe_right','swipe_left','item_claimed','pickup_arranged','picked_up','thanked','claim_expired','item_expired','item_renewed','item_marked_donated','notify_me_tapped','clearout_interest_yes','clearout_interest_no')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.events TO authenticated; GRANT ALL ON public.events TO service_role;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_events ON public.events FOR SELECT TO authenticated USING(public.is_admin());
CREATE TABLE public.synonyms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category text NOT NULL, words text[] NOT NULL CHECK(cardinality(words)>=2));
GRANT SELECT ON public.synonyms TO authenticated; GRANT ALL ON public.synonyms TO service_role;
ALTER TABLE public.synonyms ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_synonyms ON public.synonyms FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.circle_members WHERE user_id=auth.uid()));
CREATE TABLE public.item_matches (item_id uuid REFERENCES public.items(id) ON DELETE CASCADE, wish_id uuid REFERENCES public.wishes(id) ON DELETE CASCADE, user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), notified_at timestamptz, PRIMARY KEY(item_id,wish_id));
GRANT SELECT ON public.item_matches TO authenticated; GRANT ALL ON public.item_matches TO service_role;
ALTER TABLE public.item_matches ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_matches ON public.item_matches FOR SELECT TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.items i WHERE i.id=item_id));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, item_id uuid REFERENCES public.items(id), kind text NOT NULL CHECK(kind IN('match','renew','free_again')), created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
GRANT SELECT ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_notifications ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.item_watchers (item_id uuid REFERENCES public.items(id) ON DELETE CASCADE, user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(item_id,user_id));
GRANT SELECT ON public.item_watchers TO authenticated; GRANT ALL ON public.item_watchers TO service_role;
ALTER TABLE public.item_watchers ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_watchers ON public.item_watchers FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.swipe_passes (item_id uuid REFERENCES public.items(id) ON DELETE CASCADE, user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(item_id,user_id));
GRANT SELECT ON public.swipe_passes TO authenticated; GRANT ALL ON public.swipe_passes TO service_role;
ALTER TABLE public.swipe_passes ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_passes ON public.swipe_passes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.chat_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES public.claims(id), reporter_id uuid NOT NULL REFERENCES public.profiles(id), reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.chat_reports TO authenticated; GRANT ALL ON public.chat_reports TO service_role;
ALTER TABLE public.chat_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_reports ON public.chat_reports FOR SELECT TO authenticated USING(public.is_admin());
CREATE FUNCTION public.create_member_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); INSERT INTO public.events(user_id,name) VALUES(NEW.id,'signed_up'); RETURN NEW; END $$;
CREATE TRIGGER on_passalong_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_member_profile();
CREATE INDEX items_circle_newest ON public.items(circle_id,created_at DESC);
CREATE INDEX items_giver ON public.items(giver_id,created_at DESC);
CREATE INDEX wishes_circle ON public.wishes(circle_id);
CREATE INDEX claims_receiver ON public.claims(receiver_id);
CREATE INDEX messages_claim ON public.messages(claim_id,created_at);
CREATE INDEX events_week ON public.events(created_at,name);
CREATE POLICY upload_own_item_photo ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='item-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY read_own_or_circle_item_photo ON storage.objects FOR SELECT TO authenticated USING(bucket_id='item-photos' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.items i WHERE i.photo_path=name AND public.is_member(i.circle_id))));
REVOKE ALL ON FUNCTION public.create_member_profile() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated;
REVOKE ALL ON FUNCTION public.is_member(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_member(uuid) TO authenticated;